begin;

-- Local pickup, part 1: the static safe-trade-station reference data, the two new listings
-- columns, and create_listing_with_details gaining pickup params. Pickup is an ADDITIONAL
-- checkout choice alongside shipping, not a replacement -- weight/dims stay required on every
-- listing exactly as before. See 202609300059/202609300060 for checkout and escrow-release.

create table public.pickup_stations(
  id uuid primary key default gen_random_uuid(),
  jurisdiction text not null,
  city text,
  state text,
  country text not null default 'USA',
  notes text,
  created_at timestamptz not null default now()
);
create index pickup_stations_country_state on public.pickup_stations(country, state);
alter table public.pickup_stations enable row level security;
revoke all on public.pickup_stations from public,anon,authenticated;
-- Static, non-sensitive reference data (public safe-exchange-zone addresses) -- readable by
-- anyone, writable by nobody from the client, same posture as listing_media's read policy but
-- with a `true` predicate since there's no per-row ownership to scope by.
create policy pickup_stations_public_read on public.pickup_stations for select to anon, authenticated using (true);
grant select on public.pickup_stations to anon, authenticated;

-- Seed data generated from a cleaned, deduplicated real-world dataset of "safe exchange zone"
-- locations (mostly US police stations, some Canada/Brazil) via a one-off script rather than
-- hand-typed -- see the migration's originating conversation for the cleanup performed
-- (duplicate rows dropped, two rows with a blank Country defaulted to USA, one row's Notes field
-- had unrelated chat text stripped out, a couple of run-together Jurisdiction/City pairs split).

alter table public.listings
  add column pickup_enabled boolean not null default false,
  add column pickup_station_id uuid references public.pickup_stations(id);

-- create_listing_with_details gains two trailing pickup params. Same 20-arg live signature as
-- 202609300054_signature_reference_library.sql -- dropped explicitly (a changed param count
-- always needs this, or PostgREST calls resolved by named args become ambiguous between overloads,
-- same failure mode documented at 202609300046_signature_media_kind.sql).
drop function public.create_listing_with_details(text,text,text,bigint,text,text,text,text,jsonb,jsonb,jsonb,numeric,numeric,numeric,numeric,boolean,text,integer,text,text);
create function public.create_listing_with_details(
  p_title text,p_description text,p_category text,p_price_cents bigint,p_evidence text default '',
  p_issuer text default null,p_number text default null,p_company text default null,p_media jsonb default '[]',
  p_attributes jsonb default '{}',p_tags jsonb default '[]',
  p_weight_oz numeric default null,p_length_in numeric default null,p_width_in numeric default null,p_height_in numeric default null,
  p_free_shipping boolean default false,
  p_listing_type text default 'fixed',p_auction_days integer default null,
  p_signature_ai_label text default null,p_signature_ai_note text default null,
  p_pickup_enabled boolean default false,p_pickup_station_id uuid default null
) returns uuid language plpgsql security definer set search_path='' as $$
declare new_id uuid; field record; tag jsonb; clean_attributes jsonb:='{}'; clean_tags jsonb:='[]'; clean text;
  allowed text[]:=array['item_type','subject','year','condition','grading_company','grade'];
begin
  if p_listing_type not in ('fixed','auction') then raise exception 'Invalid listing type.'; end if;
  if p_listing_type='auction' and p_auction_days not in (3,5,7) then raise exception 'Choose a 3, 5, or 7 day auction.'; end if;
  if p_category='Sports' then allowed:=allowed||array['sport','team'];
  elsif p_category='Art' then allowed:=allowed||array['artist','medium','dimensions'];
  elsif p_category='Comics' then allowed:=allowed||array['publisher','issue']; end if;
  if p_attributes is null or jsonb_typeof(p_attributes)<>'object' then raise exception 'Invalid item details'; end if;
  for field in select * from jsonb_each(p_attributes) loop
    if not(field.key=any(allowed)) or jsonb_typeof(field.value)<>'string' then raise exception 'Unsupported item detail'; end if;
    clean:=btrim(field.value#>>'{}');
    if length(clean)>120 then raise exception 'Item detail too long'; end if;
    if clean<>'' then clean_attributes:=clean_attributes||jsonb_build_object(field.key,clean); end if;
  end loop;
  if p_tags is null or jsonb_typeof(p_tags)<>'array' then raise exception 'Invalid tags'; end if;
  for tag in select * from jsonb_array_elements(p_tags) loop
    if jsonb_typeof(tag)<>'string' then raise exception 'Invalid tag'; end if;
    clean:=lower(regexp_replace(btrim(tag#>>'{}'),'\s+',' ','g'));
    if length(clean)>40 then raise exception 'Tag too long'; end if;
    if clean<>'' and not(clean_tags ? clean) then clean_tags:=clean_tags||jsonb_build_array(clean); end if;
  end loop;
  if jsonb_array_length(clean_tags)>8 then raise exception 'Too many tags'; end if;
  if p_weight_oz is null or p_weight_oz<=0 or p_length_in is null or p_length_in<=0
     or p_width_in is null or p_width_in<=0 or p_height_in is null or p_height_in<=0 then
    raise exception 'Enter a valid package weight and size.';
  end if;
  if p_pickup_enabled and not exists(select 1 from public.pickup_stations where id=p_pickup_station_id) then
    raise exception 'Choose a valid pickup location.';
  end if;
  new_id:=public.create_listing_with_media(p_title,p_description,p_category,p_price_cents,p_evidence,p_issuer,p_number,p_company,p_media);
  update public.listings set attributes=clean_attributes,tags=clean_tags,
    weight_oz=p_weight_oz,length_in=p_length_in,width_in=p_width_in,height_in=p_height_in,free_shipping=coalesce(p_free_shipping,false),
    listing_type=p_listing_type,auction_ends_at=case when p_listing_type='auction' then now()+make_interval(days=>p_auction_days) else null end,
    signature_ai_label=p_signature_ai_label,signature_ai_note=nullif(btrim(coalesce(p_signature_ai_note,'')),''),
    pickup_enabled=coalesce(p_pickup_enabled,false),pickup_station_id=case when p_pickup_enabled then p_pickup_station_id else null end
    where id=new_id;
  perform public.capture_signature_reference(new_id, clean_attributes->>'subject', p_signature_ai_note);
  perform public.notify_klaviyo((select email from auth.users where id=auth.uid()),'Item Listed',
    jsonb_build_object('listing_id',new_id,'title',p_title,'category',p_category,'price_cents',p_price_cents,'listing_type',p_listing_type));
  return new_id;
end;
$$;
revoke all on function public.create_listing_with_details(text,text,text,bigint,text,text,text,text,jsonb,jsonb,jsonb,numeric,numeric,numeric,numeric,boolean,text,integer,text,text,boolean,uuid) from public,anon;
grant execute on function public.create_listing_with_details(text,text,text,bigint,text,text,text,text,jsonb,jsonb,jsonb,numeric,numeric,numeric,numeric,boolean,text,integer,text,text,boolean,uuid) to authenticated;

-- browse_listings_with_certificates(): 0-arg, plain create or replace (no drop needed -- the
-- param list is unchanged). Adds pickup_enabled and a denormalized pickup_station object (so the
-- frontend never needs a second round-trip to show the station's name/city/notes).
create or replace function public.browse_listings_with_certificates() returns jsonb
language sql stable security definer set search_path='' as $$
select coalesce(jsonb_agg(item || jsonb_build_object(
  'attributes',l.attributes,'tags',l.tags,'seller_charges_enabled',coalesce(sa.charges_enabled,false),
  'seller_member_since',p.created_at,
  'seller_sales_count',(select count(*) from public.purchases where seller_id=l.seller_id),
  'seller_rating_avg',(select round(avg(rating)::numeric,2) from public.seller_ratings where seller_id=l.seller_id),
  'seller_rating_count',(select count(*) from public.seller_ratings where seller_id=l.seller_id),
  'pickup_enabled',l.pickup_enabled,
  'pickup_station',case when l.pickup_enabled then jsonb_build_object('id',ps.id,'jurisdiction',ps.jurisdiction,'city',ps.city,'state',ps.state,'country',ps.country,'notes',ps.notes) else null end
) order by position),'[]'::jsonb)
from jsonb_array_elements(public.browse_listings_with_media()) with ordinality as items(item,position)
join public.listings l on l.id=(item->>'id')::uuid
join public.profiles p on p.id=l.seller_id
left join public.stripe_accounts sa on sa.user_id=l.seller_id
left join public.pickup_stations ps on ps.id=l.pickup_station_id;
$$;

-- my_open_buy_requests(): the buyer's own path into CheckoutAddress when reached via the buy-
-- request flow (rather than browse) -- needs the identical pickup fields or the choice silently
-- fails to render on that code path. 0-arg, plain create or replace.
create or replace function public.my_open_buy_requests() returns jsonb
language sql stable security definer set search_path='' as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',r.id,'listing_id',l.id,'title',l.title,'category',l.category,'price_cents',l.price_cents,'status',r.status,'expires_at',r.expires_at,
    'pickup_enabled',l.pickup_enabled,
    'pickup_station',case when l.pickup_enabled then jsonb_build_object('id',ps.id,'jurisdiction',ps.jurisdiction,'city',ps.city,'state',ps.state,'country',ps.country,'notes',ps.notes) else null end,
    'media',coalesce((select jsonb_agg(jsonb_build_object('path',m.path,'kind',m.kind) order by m.position) from public.listing_media m where m.listing_id=l.id and m.kind='item'),'[]'::jsonb)
  ) order by r.created_at desc),'[]'::jsonb)
  from public.availability_requests r join public.listings l on l.id=r.listing_id
  left join public.pickup_stations ps on ps.id=l.pickup_station_id
  where r.buyer_id=auth.uid() and r.status in ('pending','confirmed') and r.expires_at>now();
$$;

commit;
